/* zb_xlnx_cfg.c - configuration tables for the Xilinx drivers (normally generated by the
 * Vitis BSP as xvtc_g.c / xv_frmbufrd_g.c / xv_frmbufwr_g.c), zed_base v6 hardware.
 * The frame buffer limits only gate the driver's argument checks; BGRX8 is the format
 * zed_base uses. Adjust if the IP configuration in Vivado differs. */
#include "xparameters.h"
#include "xvtc.h"
#include "xv_frmbufrd.h"
#include "xv_frmbufwr.h"

XVtc_Config XVtc_ConfigTable[] = {
    { "vtc", XPAR_VTC_BASEADDR, 0, 0 },
    { NULL, 0, 0, 0 }
};

/* Name, Base, PPC, MaxW, MaxH, MaxDataWidth, AXIMM data/addr width, then format enables */
XV_frmbufrd_Config XV_frmbufrd_ConfigTable[] = {
    { .Name = "vfb_rd",  .BaseAddress = XPAR_VFB_RD_BASEADDR,  .PixPerClk = 1, .MaxWidth = 4096, .MaxHeight = 2160,
      .MaxDataWidth = 8, .AXIMMDataWidth = 64, .AXIMMAddrWidth = 32, .RGBX8En = 1, .BGRX8En = 1 },
    { .Name = "vfb_rd2", .BaseAddress = XPAR_VFB_RD2_BASEADDR, .PixPerClk = 1, .MaxWidth = 4096, .MaxHeight = 2160,
      .MaxDataWidth = 8, .AXIMMDataWidth = 64, .AXIMMAddrWidth = 32, .RGBX8En = 1, .BGRX8En = 1 },
    { .Name = NULL }
};
XV_frmbufwr_Config XV_frmbufwr_ConfigTable[] = {
    { .Name = "vfb_wr",  .BaseAddress = XPAR_VFB_WR_BASEADDR,  .PixPerClk = 1, .MaxWidth = 4096, .MaxHeight = 2160,
      .MaxDataWidth = 8, .AXIMMDataWidth = 64, .AXIMMAddrWidth = 32, .RGBX8En = 1, .BGRX8En = 1 },
    { .Name = NULL }
};
